function SearchResults({ initialQuery }: { initialQuery: string }) {
  const [query, setQuery] = useState(initialQuery);

  function onChange(e: React.ChangeEvent<HTMLInputElement>) {
    setQuery(e.target.value); // urgent update drives the results read
  }

  return (
    <div>
      <input value={query} onChange={onChange} placeholder="Search" />
      <Suspense key={query} fallback={<ResultsSkeleton />}>
        <ResultsList query={query} />
      </Suspense>
    </div>
  );
}

function ResultsList({ query }: { query: string }) {
  // suspends on a cached resource keyed by query
  const rows = useSearchResource(query).read();
  return (
    <ul>
      {rows.map((r) => (
        <li key={r.id}>{r.title}</li>
      ))}
    </ul>
  );
}
